    int side;
    for (side = 0; side < 2; side++)
        localArmies[side] = *m_armyGroups[side];

    aiAutoCombat(m_heroes[0], m_heroes[1], &localArmies[0], &localArmies[1],
                   m_defendingTown, m_combatCell);

