unsigned char combatManager::isOutsidePlacementBoundry(int group, int index)
{
    if (group == 0)
        return index % COMBAT_GRID_ROW_STRIDE
            > m_placementBoundaryDepth * 2 + 1;
    return index % COMBAT_GRID_ROW_STRIDE
        < m_placementBoundaryDepth * 2 + 15;
}

